  sec('5 · GST COUNCIL AND THE CONSTITUTION', 'b'),
  t('<b>Constitution (101st Amendment) Act, 2016</b> (notified <b>08.09.2016</b>)', '<b>Art 246A:</b> concurrent levy and collection by Centre and States', '<b>Art 269A:</b> Centre levies <b>IGST</b> on inter-State supplies incl. imports', '<b>Compensation</b> to States for <b>five years</b> on Council recommendation (handout: “Clause 19”)', '<b>Petroleum:</b> crude, high speed diesel, petrol, natural gas, ATF brought under GST from a later date', w=20),
