  tb(['Ledger effect', 'Assets', 'Liabilities'], ['Capital Expenditure', '↑', '↓ (or no rise)'], ['Capital Receipts', '↓', '↑']),
  bx('ye', '<b>Rules:</b> interest = RE, principal = CE. <b>Defence:</b> salaries, rations, ammunition = RE; jets, carriers = CE. <b>Any transfer to a State except a loan = RE</b> (leads to ERD).'),
  sec('4 · DEFICIT vs DEBT, BD, MONETISATION, WMA ' + P('Prelims deficits'), 'r'),
  t('<b>Deficit vs debt</b>', 'deficit = <b>flow</b> (yearly); debt = <b>stock</b> (all unpaid past deficits)', '<b>BD = TE − TR</b>; TE = intentions, TR = capabilities; habitual BD = “political theatricality”', '<b>CADP (1974)</b> announced canals unfunded → <b>AIBP (1996)</b> to finish', '<b>Monetised deficit:</b> BD financed by <b>RBI printing money</b> against govt bonds', w=18),
