  t('<b>WMA (1997)</b>', 'RBI-govt agreements <b>abolished BD and monetisation</b>; govt promised <b>no BD</b>', 'RBI helps <b>temporary mismatch</b>; two loans to Centre and States', t('<b>Normal WMA</b>', 'short term, unsecured overdraft on minimum balance'), t('<b>Special WMA</b>', 'beyond Normal limit; collateral (G-Secs, T-Bills)'), 'RBI and govts meet <b>before each budget</b>; strictly short term', w=18),
  t('<b>Market discipline fails</b>', 'borrower is not the repayer; Friedman: spending like alcohol, hangover (inflation) later', '<b>Inter-generational:</b> children repay; <b>Oil Bonds (2005-2012)</b> to oil marketing companies instead of raising petrol prices', '<b>Intra-generational:</b> <b>crowding out</b>, inflation hurts poor (Engel’s law)', 'debt not bad itself: <b>multiplier</b> (AD = C + G + I + X − M); unsustainable = recession with very high inflation', w=20),
  sec('5 · FRBM AND THE FAMILY OF DEFICITS ' + P('Prelims, Mains FRBM'), 'b'),
  t('<b>FRBM Act, 2003</b> (Parliament bound its hands)', '<b>FD within 3% of GDP</b>, 5 years', '<b>eliminate RD</b>, 5 years', t('<b>three statements</b>', '<b>Macro-Economic Framework Statement:</b> growth, GDP, external sector', '<b>Medium-Term Fiscal Policy (MTFP):</b> <b>three-year rolling</b> targets FD, RD, Debt', '<b>Fiscal Policy Strategy Statement:</b> priorities, tax/expenditure policy, justification of deviations'), '= “fiscal consolidation roadmap”; deadlines missed, credibility fell', w=20),
